rss.channel:
    	{{ site.Title }}
    	{{ site.BaseURL }}
    	{{ with site.Params.description }}{{ . }}{{ else }}Recent content on {{ site.Title }}{{ end }}
    	{{ site.Language.LanguageCode | default site.Language.Lang }}
    	{{ site.Params.contactEmail }} ({{ site.Params.author }})
    	{{ site.Params.contactEmail }} ({{ site.Params.author }})
    	© {{ now.Year }} {{ site.Params.author }}
    	{{ now.Format "Mon, 02 Jan 2006 15:04:05 -0700" | safeHTML }}
    	Hugo {{ hugo.Version }}


		{{ $posts := where site.RegularPages "Section" "posts" }}
		{{ range first 24 $posts }}
		{{ $feature := .Resources.GetMatch "feature.*" }}
		{{ $xl := "" }}
		{{ $alt := .Title }}
		{{ with .Params.feature_image_alt }}{{ $alt = . }}{{ end }}
		{{ if $feature }}{{ $xl = $feature.Resize "1920x" }}{{ end }}


			{{ "" | safeHTML }}{{ .Title }}{{ "" | safeHTML }}
			{{ .Permalink }}
			{{ .Date.Format "Mon, 02 Jan 2006 15:04:05 -0700" | safeHTML }}
			{{ .Permalink }}
			{{ site.Params.author }}

			{{ range .Params.de }}
				{{ $de := site.GetPage (printf "/de/%s" .) }}
				{{ with $de }}{{ .Title }}{{ else }}{{ . }}{{ end }}
			{{ end }}

			{{ "" | safeHTML }}{{ .Summary | plainify | truncate 280 }}{{ "" | safeHTML }}

			{{ "" | safeHTML }}
			{{ with $xl }}<p><img src="{{ .Permalink }}" alt="{{ $alt }}" /></p>{{ end }}
			{{ .Content | safeHTML }}
			<img src="https://tinylytics.app/pixel/bUqbbv9aC4svM35xagZs.gif?path={{ .RelPermalink }}" alt="" style="width:1px;height:1px;border:0;" />
			{{ "" | safeHTML }}

			{{ with $xl }}


			{{ $alt }}
			{{ with $.Params.feature_image_caption }}{{ . | plainify }}{{ end }}


			{{ end }}

		{{ end }}
